<script setup lang="ts">
import { metrics, strategyNames, kindNames } from '../domain'
import type { SavedState } from '../store'
import { defaultSceneLayout,nodePath,kindLabels,sceneOutline } from '../sceneGraph'
defineProps<{snapshot:SavedState}>()
const labels={mapping:'关联与错配',period:'发布周期',strategy:'策略权衡',transfer:'独立迁移',limits:'结论边界'}
</script>
<template><div class="submitted-evidence"><h2>学生结论</h2><article v-for="(label,key) in labels" :key="key"><h3>{{ label }}</h3><p class="evidence-text">{{ snapshot.conclusions[key] || '未填写' }}</p></article><h2>仿真对照</h2><div class="table-scroll"><table><thead><tr><th>记录 / 类型</th><th>策略 / 周期</th><th>发布数 / 尖峰可见</th><th>误触发 / 延迟</th><th>切换 / 恢复</th></tr></thead><tbody><tr v-for="t in snapshot.trials" :key="t.id"><td>#{{ t.id }} {{ kindNames[t.kind] }}</td><td>{{ strategyNames[t.config.strategy] }} / {{ t.config.period }}s</td><td>{{ metrics(t).published }} / {{ metrics(t).visibleSpike?'可见':'未见' }}</td><td>{{ metrics(t).falseTriggers }} / {{ metrics(t).delay===null?'未检出':metrics(t).delay+'s' }}</td><td>{{ metrics(t).switches }} / {{ metrics(t).recoveryAt ?? '—' }}</td></tr></tbody></table></div><h2>提交时的场景结构 · 修订{{ snapshot.sceneLayout?.revision ?? 0 }}</h2><div class="submitted-scene-tree"><p v-for="node in sceneOutline(snapshot.sceneLayout ?? defaultSceneLayout())" :key="node.id" :style="{paddingLeft:((nodePath(snapshot.sceneLayout ?? defaultSceneLayout(),node.id).length-1)*16)+'px'}">{{ kindLabels[node.kind] }} · {{ node.name }}<small> {{ node.id }} · {{ node.modelRef }}</small></p></div><h2>冻结的配置与证据</h2><details><summary>提交时的最终配置</summary><pre>{{ JSON.stringify(snapshot.config,null,2) }}</pre></details><details v-for="t in snapshot.trials" :key="t.id"><summary>仿真记录#{{ t.id }} · 场景修订{{ t.sceneRevision ?? 0 }} · {{ t.tick }}/40秒 · {{ t.dataset }}</summary><div><h3>运行前预测</h3><p class="evidence-text">{{ t.prediction }}</p><p v-for="(e,i) in t.predictionHistory" :key="i" class="core-small">修订{{ i+1 }} · {{ new Date(e.at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}) }} · {{ e.text }}</p><h3>本轮配置</h3><pre>{{ JSON.stringify(t.config,null,2) }}</pre><h3>观察与关联链</h3><p v-for="(o,i) in t.observations" :key="i" class="evidence-text">源{{ o.tick }}s，发布{{ o.displayTick ?? o.tick }}s：{{ o.model }}模型 → {{ o.code }} → {{ o.field }} → {{ o.value ?? '—' }} {{ o.unit }} · {{ o.quality }}<br>{{ o.note }}</p><h3>检测与事件</h3><p>{{ t.detections.map(e=>e.tick+'s '+e.type).join('；') || '无检测事件' }}</p><p v-for="e in t.incidents" :key="e.id">事件{{ e.id }}：触发{{ e.triggeredAt }}；确认{{ e.acknowledgedAt ?? '—' }}；恢复{{ e.recoveredAt ?? '—' }}；关闭{{ e.closedAt ?? '—' }}</p><details><summary>完整源样本与发布样本</summary><pre>{{ JSON.stringify({source:t.samples,published:t.published},null,2) }}</pre></details></div></details><details><summary>操作与配置变更历史</summary><pre>{{ JSON.stringify(snapshot.logs,null,2) }}</pre></details></div></template>
